import React, { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useTheme } from "../context/ThemeContext";
import {
  Calendar, Trophy, Users, LayoutDashboard,
  LogOut, Sun, Moon, Menu, X, Shield
} from "lucide-react";

const navItems = [
  { to: "/fixtures",    label: "Fixtures",     icon: Calendar },
  { to: "/leaderboard", label: "Leaderboard",  icon: Trophy },
  { to: "/predictions", label: "Predictions",  icon: Users },
];

export default function Layout({ children }) {
  const { profile, logout } = useAuth();
  const { dark, toggle } = useTheme();
  const navigate = useNavigate();
  const [mobileOpen, setMobileOpen] = useState(false);

  const handleLogout = async () => {
    await logout();
    navigate("/login");
  };

  const isAdmin = profile?.role === "admin";

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-950 text-gray-900 dark:text-white font-body">
      {/* Top navbar */}
      <header className="sticky top-0 z-50 bg-white dark:bg-fifa-navy border-b border-gray-200 dark:border-white/10 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          {/* Logo */}
          <NavLink to="/fixtures" className="flex items-center gap-2">
            <span className="text-2xl">🏆</span>
            <div className="hidden sm:block">
              <span className="font-display text-2xl text-fifa-blue dark:text-fifa-gold tracking-widest">
                WC2026
              </span>
              <span className="text-xs text-gray-500 dark:text-gray-400 block -mt-1 tracking-wider">
                PREDICTION LEAGUE
              </span>
            </div>
          </NavLink>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-1">
            {navItems.map(({ to, label, icon: Icon }) => (
              <NavLink
                key={to}
                to={to}
                className={({ isActive }) =>
                  `flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-150 ${
                    isActive
                      ? "bg-fifa-blue dark:bg-fifa-gold text-white dark:text-fifa-navy"
                      : "text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/10"
                  }`
                }
              >
                <Icon size={16} />
                {label}
              </NavLink>
            ))}
            {isAdmin && (
              <NavLink
                to="/admin"
                className={({ isActive }) =>
                  `flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-150 ${
                    isActive
                      ? "bg-purple-600 text-white"
                      : "text-purple-600 dark:text-purple-400 hover:bg-purple-50 dark:hover:bg-purple-900/20"
                  }`
                }
              >
                <Shield size={16} />
                Admin
              </NavLink>
            )}
          </nav>

          {/* Right side actions */}
          <div className="flex items-center gap-2">
            {/* User chip */}
            <div className="hidden sm:flex items-center gap-2 px-3 py-1.5 bg-gray-100 dark:bg-white/10 rounded-full">
              <div className="w-6 h-6 rounded-full bg-gradient-to-br from-fifa-gold to-yellow-600 flex items-center justify-center text-xs font-bold text-fifa-navy">
                {profile?.displayName?.[0]?.toUpperCase() || "?"}
              </div>
              <span className="text-sm font-medium text-gray-700 dark:text-gray-200">
                {profile?.displayName || "User"}
              </span>
              {isAdmin && (
                <span className="text-xs bg-purple-100 dark:bg-purple-900/50 text-purple-700 dark:text-purple-300 px-1.5 py-0.5 rounded-full font-semibold">
                  ADMIN
                </span>
              )}
            </div>

            {/* Theme toggle */}
            <button
              onClick={toggle}
              className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 transition text-gray-600 dark:text-gray-400"
            >
              {dark ? <Sun size={18} /> : <Moon size={18} />}
            </button>

            {/* Logout */}
            <button
              onClick={handleLogout}
              className="hidden sm:flex p-2 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-gray-500 dark:text-gray-400 hover:text-red-600 dark:hover:text-red-400 transition"
            >
              <LogOut size={18} />
            </button>

            {/* Mobile menu button */}
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              className="md:hidden p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 transition"
            >
              {mobileOpen ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>

        {/* Mobile nav */}
        {mobileOpen && (
          <div className="md:hidden border-t border-gray-200 dark:border-white/10 bg-white dark:bg-fifa-navy px-4 py-3 space-y-1">
            <div className="flex items-center gap-2 px-3 py-2 mb-2">
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-fifa-gold to-yellow-600 flex items-center justify-center text-sm font-bold text-fifa-navy">
                {profile?.displayName?.[0]?.toUpperCase() || "?"}
              </div>
              <div>
                <p className="font-medium text-sm">{profile?.displayName}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">{profile?.email}</p>
              </div>
            </div>
            {navItems.map(({ to, label, icon: Icon }) => (
              <NavLink
                key={to}
                to={to}
                onClick={() => setMobileOpen(false)}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition ${
                    isActive
                      ? "bg-fifa-blue dark:bg-fifa-gold text-white dark:text-fifa-navy"
                      : "text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/10"
                  }`
                }
              >
                <Icon size={18} />
                {label}
              </NavLink>
            ))}
            {isAdmin && (
              <NavLink
                to="/admin"
                onClick={() => setMobileOpen(false)}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition ${
                    isActive
                      ? "bg-purple-600 text-white"
                      : "text-purple-600 dark:text-purple-400 hover:bg-purple-50 dark:hover:bg-purple-900/20"
                  }`
                }
              >
                <Shield size={18} />
                Admin Panel
              </NavLink>
            )}
            <button
              onClick={handleLogout}
              className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition w-full"
            >
              <LogOut size={18} />
              Sign Out
            </button>
          </div>
        )}
      </header>

      {/* Page content */}
      <main className="max-w-7xl mx-auto px-4 py-6">
        {children}
      </main>
    </div>
  );
}
